const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const montePisano = ee.Geometry.Point([10.5, 43.8]).buffer(10000); // 10km buffer around Monte Pisano
  const startDate = '2019-02-24';
  const endDate = '2019-02-27'; // Exclusive end date

  // 2. Data Acquisition - MODIS Active Fire Data
  const fireCollection = ee.ImageCollection('MODIS/006/MOD14A1')
    .filterDate(startDate, endDate)
    .filterBounds(montePisano);

  const collectionSize = fireCollection.size().getInfo();
  console.log(`Fire detection images found: ${collectionSize}`);

  // Check for empty collection
  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Count fire pixels
  // FireMask values: 0=not processed, 1-3=water/land/unclassified, 4-9=fire with varying confidence
  const fireMask = fireCollection.select('FireMask');

  // Create composite and count fire pixels (confidence levels 4-9)
  const fireComposite = fireMask.max();
  const fireCount = fireComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: montePisano,
    scale: 1000,
    maxPixels: 1e9
  }).get('FireMask').getInfo();

  console.log(`Valid fire pixels detected: ${fireCount}`);

  // Check for no valid pixels
  if (fireCount === 0) {
    console.log("<answer>B</answer>");
    return;
  }

  // 4. Calculation - Check if any high-confidence fires exist
  // Count pixels with fire confidence levels (7-9 = high confidence)
  const highConfFire = fireComposite.gt(6); // Values 7,8,9 are high confidence fires
  const highConfCount = highConfFire.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: montePisano,
    scale: 1000,
    maxPixels: 1e9
  }).get('FireMask').getInfo();

  console.log(`High confidence fire pixels: ${highConfCount}`);

  // 5. Validation & Final Answer
  if (highConfCount === null || highConfCount === undefined || isNaN(highConfCount)) {
    console.log("<answer>C3</answer>");
  } else if (highConfCount > 0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
